// ================= SETTINGS (fill this in) =================
const NTFY_TOPIC = 'errorhandling-abdomario7a1';  // same topic as your Steam alerts
// Don't repeat the same error from the same workflow more than once per:
const QUIET_MINUTES = 60;
// ============================================================

const d = $input.first().json;
const workflowName = d.workflow?.name ?? 'Unknown workflow';

// Errors can come from a normal run ("execution") or from the trigger itself ("trigger")
const err = d.execution?.error ?? d.trigger?.error ?? {};
const message = err.message || 'Unknown error';
const failedNode = d.execution?.lastNodeExecuted ?? (d.trigger ? 'Trigger' : 'unknown');
const link = d.execution?.url;

// Anti-spam: a workflow that runs every 5 minutes would otherwise
// send the same alert every 5 minutes until you fix it.
const state = $getWorkflowStaticData('global');
state.recent = state.recent ?? {};
const key = `${workflowName}|${message}`.slice(0, 300);
const nowMs = Date.now();
for (const k of Object.keys(state.recent)) {
  if (nowMs - state.recent[k] > QUIET_MINUTES * 60000) delete state.recent[k];
}
if (state.recent[key]) {
  return [{ json: { status: 'Skipped (same error already sent recently)', workflowName, message } }];
}
state.recent[key] = nowMs;

const when = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Amman' });
const body = {
  topic: NTFY_TOPIC,
  title: `Workflow failed: ${workflowName}`,
  message: `Node: ${failedNode}\nError: ${message.slice(0, 500)}\nTime: ${when}`,
  tags: ['warning'],
  priority: 4,
};
if (link) body.click = link; // tapping the alert on your PC opens the failed run

await this.helpers.httpRequest({ method: 'POST', url: 'https://ntfy.sh/', body, json: true });

return [{ json: { status: 'Alert sent', workflowName, failedNode, message } }];
